css:
/* 玻璃拟态：昼夜双版（:root 为日间基线，[data-reader-theme="night"] 覆盖夜景）；正文区占页高 80%+（蓝图硬约束①） */
:root{
  --gl-bg:#eef1f9; --gl-fg:#1d2333; --gl-dim:#5f6879;
  --gl-accent:#4f46e5; --gl-accent2:#0ea5e9;
  --gl-panel:rgba(255,255,255,.46); --gl-border:rgba(255,255,255,.62);
}
[data-reader-theme="night"]{
  --gl-bg:#0c0f18; --gl-fg:#e8ecf7; --gl-dim:#93a0b8;
  --gl-accent:#8b5cf6; --gl-accent2:#22d3ee;
  --gl-panel:rgba(24,29,44,.52); --gl-border:rgba(255,255,255,.14);
}
html,body{margin:0;padding:0;background:var(--gl-bg);color:var(--gl-fg);
  font-family:-apple-system,"Noto Sans CJK SC","Source Han Sans SC",sans-serif;
  font-size:var(--md-font-size,18px);line-height:var(--md-line-height,1.8);}
body::before,body::after{content:"";position:absolute;pointer-events:none;border-radius:50%;filter:blur(56px);opacity:.75;}
body::before{left:-12%;top:-16%;width:58%;height:40%;background:radial-gradient(circle,var(--gl-accent),transparent 68%);}
body::after{right:-14%;bottom:-18%;width:62%;height:42%;background:radial-gradient(circle,var(--gl-accent2),transparent 68%);}
.gl-head,.gl-body,.gl-foot,.gl-title{position:relative;}
.gl-head{display:flex;justify-content:space-between;align-items:baseline;gap:.6em;
  padding:.7em 1.15em .55em;font-size:.78em;color:var(--gl-dim);
  background:var(--gl-panel);border-bottom:1px solid var(--gl-border);
  -webkit-backdrop-filter:blur(14px) saturate(1.25);backdrop-filter:blur(14px) saturate(1.25);}
.gl-chapter{max-width:72%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.gl-pct{color:var(--gl-accent);font-variant-numeric:tabular-nums;}
.gl-title{display:flex;align-items:baseline;gap:.7em;padding:1.05em 1.15em .5em;}
.gl-title-main{font-size:1.9em;font-weight:700;letter-spacing:.03em;
  background:linear-gradient(96deg,var(--gl-accent),var(--gl-accent2));
  -webkit-background-clip:text;background-clip:text;color:transparent;}
.gl-title-sub{font-size:.72em;letter-spacing:.4em;color:var(--gl-dim);}
.gl-body{padding:.75em 1.25em 0;}
.gl-body .reader-chapter-title{margin:0 0 .65em;font-size:1.32em;font-weight:650;}
.gl-body .reader-paragraph{margin:0 0 .95em;text-indent:2em;}
.gl-body p{margin:0 0 .95em;}
.gl-body a{color:var(--gl-accent);text-decoration:none;border-bottom:1px solid var(--gl-border);}
.gl-body blockquote{margin:0 0 1em;padding:.5em .95em;border-radius:10px;
  background:var(--gl-panel);border-left:2px solid var(--gl-accent);color:var(--gl-dim);}
.gl-body code{background:rgba(127,127,127,.16);padding:.14em .36em;border-radius:5px;}
.gl-body pre{background:var(--gl-panel);padding:.85em;border-radius:12px;overflow-x:auto;
  -webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);}
.gl-body table{width:100%;border-collapse:collapse;}
.gl-body th,.gl-body td{border:1px solid var(--gl-border);padding:.35em .55em;}
.gl-foot{display:flex;justify-content:space-between;gap:.8em;padding:.55em 1.15em .75em;
  font-size:.72em;color:var(--gl-dim);font-variant-numeric:tabular-nums;
  background:var(--gl-panel);border-top:1px solid var(--gl-border);
  -webkit-backdrop-filter:blur(14px) saturate(1.25);backdrop-filter:blur(14px) saturate(1.25);}
@media (prefers-reduced-motion:reduce){body::before,body::after{filter:blur(48px);}}
